{
  "vulnerable_symbols": [
    "axios.formToJSON",
    "formToJSON",
    "formDataToJSON"
  ],
  "trigger": "当不可信 FormData 字段名包含大量嵌套方括号段，并被 axios.formToJSON 或 Content-Type 为 application/json 的 axios FormData 请求序列化时触发。",
  "exploit_evidence": [
    {
      "src": 5,
      "kind": "poc",
      "quote": "The function recurses once per bracket-delimited segment in a FormData key name with no depth limit, so a key like a[x][x][x]... with 15,000+ segments exhausts the call stack."
    }
  ],
  "fixed_version": "1.18.0",
  "summary_zh": "axios formToJSON 深层嵌套键名可致栈溢出 DoS，请升级 1.18.0。"
}
